                        for line in f:
                            p = line.split(",")
                            if len(p) >= 5:
                                a.append((int(p[0]), float(p[1]), float(p[2]), float(p[3]), float(p[4])))
        a.sort()
        _oc[(ex, mk, sym)] = ([x[0] for x in a], a) if a else None
    return _oc[(ex, mk, sym)]


